export function fakePayslipItems() {
  return ITEMS.map(([y, x, s]) => ({ y, x, s }));
}

export async function fakePayslipPdf(): Promise<Uint8Array> {
  const doc = new PDFDocument({ size: [595.32, 841.92], margin: 0 });
  const chunks: Buffer[] = [];
  doc.on('data', (c: Buffer) => chunks.push(c));
  const done = new Promise<Buffer>((r) => doc.on('end', () => r(Buffer.concat(chunks))));
  doc.font(FONT).fontSize(7);
  for (const [y, x, s] of ITEMS) {
    // pdfkit отсчитывает y сверху и от верха строки; pdf.js — базовую линию снизу.
    doc.text(s, x, 841.92 - y - 7 * 0.82, { lineBreak: false });
  }
  doc.end();
  return new Uint8Array(await done);
}
